-- =============================================================================
-- 045_corp_marketing_plan.sql
-- Corporate Marketing Activities Plan (source: KG Corporate Marketing_Plan_and_Activities.xlsx)
--   - 49 parent activities per year (FP-006..FP-044, DM-059..DM-069)
--   - 196 tasks per month x 12 months = 2,352 task rows per year
--   - 100 event shells (EVT-001..EVT-100), metrics computed at read time
-- =============================================================================

CREATE TABLE dbo.CorpMarketingPlanItem (
  CorpPlanItemID  INT IDENTITY(1,1) PRIMARY KEY,
  PlanYear        INT           NOT NULL,
  ParentCode      NVARCHAR(20)  NOT NULL,
  MainActivityKpi NVARCHAR(1000) NOT NULL,
  ResponsibleRole NVARCHAR(200) NULL,
  SourceRef       NVARCHAR(50)  NULL,
  CreatedAt       DATETIME2     NOT NULL DEFAULT SYSUTCDATETIME(),
  UpdatedAt       DATETIME2     NULL,
  CONSTRAINT UQ_CorpMarketingPlanItem UNIQUE (PlanYear, ParentCode)
);
GO

CREATE TABLE dbo.CorpMarketingTask (
  CorpTaskID         INT IDENTITY(1,1) PRIMARY KEY,
  PlanYear           INT            NOT NULL,
  Month              TINYINT        NOT NULL,
  TaskId             NVARCHAR(50)   NOT NULL,
  ParentCode         NVARCHAR(20)   NOT NULL,
  TaskIndex          TINYINT        NOT NULL,
  TaskName           NVARCHAR(1000) NOT NULL,
  ResponsibleRole    NVARCHAR(200)  NULL,
  ResponsiblePerson  NVARCHAR(200)  NULL,
  Status             NVARCHAR(30)   NOT NULL DEFAULT 'Not Verified',
  CompletionPercent  DECIMAL(5,2)   NULL,
  EvidenceRemarks    NVARCHAR(2000) NULL,
  VerificationNote   NVARCHAR(500)  NULL,
  VerifiedByUserID   INT            NULL,
  VerifiedAt         DATETIME2      NULL,
  CreatedAt          DATETIME2      NOT NULL DEFAULT SYSUTCDATETIME(),
  UpdatedAt          DATETIME2      NULL,
  CONSTRAINT UQ_CorpMarketingTask_TaskId UNIQUE (TaskId),
  CONSTRAINT FK_CorpMarketingTask_PlanItem FOREIGN KEY (PlanYear, ParentCode)
    REFERENCES dbo.CorpMarketingPlanItem (PlanYear, ParentCode),
  CONSTRAINT FK_CorpMarketingTask_Verifier FOREIGN KEY (VerifiedByUserID)
    REFERENCES dbo.[User] (UserID),
  CONSTRAINT CK_CorpMarketingTask_Month CHECK (Month BETWEEN 1 AND 12)
);
GO

CREATE INDEX IX_CorpMarketingTask_YearMonth ON dbo.CorpMarketingTask (PlanYear, Month);
CREATE INDEX IX_CorpMarketingTask_Status ON dbo.CorpMarketingTask (Status);
CREATE INDEX IX_CorpMarketingTask_Parent ON dbo.CorpMarketingTask (ParentCode);
GO

CREATE TABLE dbo.CorpMarketingEvent (
  CorpEventID        INT IDENTITY(1,1) PRIMARY KEY,
  EventCode          NVARCHAR(20)   NOT NULL,
  Category           NVARCHAR(100)  NULL,
  EventName          NVARCHAR(300)  NULL,
  BusinessUnit       NVARCHAR(100)  NULL,
  ResponsiblePerson  NVARCHAR(200)  NULL,
  ResponsibleRole    NVARCHAR(200)  NULL,
  Location           NVARCHAR(200)  NULL,
  StartDate          DATE           NULL,
  EndDate            DATE           NULL,
  Status             NVARCHAR(30)   NOT NULL DEFAULT 'Planned',
  PlannedParticipants INT            NULL,
  ActualParticipants  INT            NULL,
  LeadsGenerated      INT            NULL,
  Conversions         INT            NULL,
  PlannedRevenue      DECIMAL(18,2)  NULL,
  ActualRevenue       DECIMAL(18,2)  NULL,
  ApprovedBudget      DECIMAL(18,2)  NULL,
  ActualCost          DECIMAL(18,2)  NULL,
  ReachImpressions    BIGINT         NULL,
  Engagements         INT            NULL,
  SatisfactionScore   DECIMAL(5,2)   NULL,
  KpiTarget           NVARCHAR(500)  NULL,
  KpiActual           NVARCHAR(500)  NULL,
  EvidenceLink        NVARCHAR(500)  NULL,
  Remarks             NVARCHAR(2000) NULL,
  CreatedAt           DATETIME2      NOT NULL DEFAULT SYSUTCDATETIME(),
  UpdatedAt           DATETIME2      NULL,
  CONSTRAINT UQ_CorpMarketingEvent_EventCode UNIQUE (EventCode)
);
GO

